def brave_image_search(api_key, q, count=None, client_metadata=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0232000" if __import__("os").path.isdir("./environment_mix/0232000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool_name = "brave_image_search"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _day_bucket_iso(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        b = datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)
        return _iso(b)

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s.strip():
            return None
        s2 = s.strip()
        try:
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000):013d}{random.randint(0, 999999):06d}"

    def _normalize_key_param(v):
        if not isinstance(v, str):
            return None
        return v.strip()

    def _coerce_int(v):
        if v is None:
            return None
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v
        if isinstance(v, str):
            s = v.strip()
            if s == "":
                return None
            try:
                return int(s)
            except Exception:
                return None
        return None

    def _auth_api_key(api_key_value):
        # Authenticate against client-visible value or id/prefix; never against key_hash.
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        av = _normalize_key_param(api_key_value)
        if not av:
            return None

        # Prefer exact id match, then prefix match (some clients pass prefix), then any active key that matches.
        candidates = []
        for r in keys:
            if not isinstance(r, dict):
                continue
            rid = r.get("id")
            pref = r.get("key_prefix")
            if rid == av:
                candidates.append(r)
            elif isinstance(pref, str) and pref and av.startswith(pref):
                candidates.append(r)

        if not candidates:
            return None

        # Pick an active key if available; else first match.
        for r in candidates:
            if r.get("status") == "active":
                return r
        return candidates[0]

    def _is_tool_allowed(key_row):
        allowed = key_row.get("allowed_tools")
        if allowed is None:
            return True
        if not isinstance(allowed, list):
            return False
        if len(allowed) == 0:
            return True
        return tool_name in allowed

    def _ensure_counter_row(counters, api_key_id, usage_date_iso):
        now_iso = _iso(_now_utc())
        for r in counters:
            if r.get("api_key_id") == api_key_id and r.get("usage_date") == usage_date_iso and r.get("tool_name") == tool_name:
                return r
        row = {
            "id": _gen_id("bsmcp_use"),
            "api_key_id": api_key_id,
            "usage_date": usage_date_iso,
            "tool_name": tool_name,
            "request_count": 0,
            "success_count": 0,
            "error_count": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        counters.append(row)
        return row

    def _increment_usage(api_key_id, usage_date_iso, final_status):
        counters = _load("usage_counters.json")
        if not isinstance(counters, list):
            counters = []
        row = _ensure_counter_row(counters, api_key_id, usage_date_iso)
        row["request_count"] = int(row.get("request_count") or 0) + 1
        if final_status == "succeeded":
            row["success_count"] = int(row.get("success_count") or 0) + 1
        else:
            row["error_count"] = int(row.get("error_count") or 0) + 1
        row["updated_at"] = _iso(_now_utc())
        # Enforce success+error <= request (defensive)
        sc = int(row.get("success_count") or 0)
        ec = int(row.get("error_count") or 0)
        rc = int(row.get("request_count") or 0)
        if sc + ec > rc:
            row["request_count"] = sc + ec
        _save("usage_counters.json", counters)

    def _sum_daily_requests(counters, api_key_id, usage_date_iso):
        total = 0
        for r in counters:
            if r.get("api_key_id") == api_key_id and r.get("usage_date") == usage_date_iso:
                try:
                    total += int(r.get("request_count") or 0)
                except Exception:
                    pass
        return total

    def _rate_limited(counters, api_key_id, burst_rps_limit):
        if burst_rps_limit is None:
            return False
        try:
            limit = float(burst_rps_limit)
        except Exception:
            return False
        if limit <= 0:
            return False

        # Count requests in the last 1.0s from search_requests log (more accurate than counters).
        # If file missing/unparseable, do not rate-limit.
        reqs = _load("search_requests.json")
        if not isinstance(reqs, list):
            return False
        now = _now_utc()
        window_start = now - datetime.timedelta(seconds=1)
        cnt = 0
        for r in reqs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            created = _parse_rfc3339(r.get("created_at"))
            if created is None:
                continue
            if created >= window_start:
                cnt += 1
        return cnt >= limit

    # -------- Validate inputs --------
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")

    if not isinstance(q, str) or not q.strip():
        return _err("VALIDATION_ERROR", "q must be a non-empty string", field="q")

    if client_metadata is not None and not isinstance(client_metadata, dict):
        return _err("VALIDATION_ERROR", "client_metadata must be an object", field="client_metadata")

    requested_limit = _coerce_int(count)
    if requested_limit is None:
        requested_limit = 20
    if requested_limit < 1:
        return _err("VALIDATION_ERROR", "count must be >= 1", field="count")
    # Cap is 20; record requested_limit even if >20
    effective_limit = max(1, min(20, requested_limit))

    # -------- Authenticate --------
    key_row = _auth_api_key(api_key)
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key", tool_name=tool_name)

    api_key_id = key_row.get("id")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active", tool_name=tool_name, api_key_id=api_key_id)

    if not _is_tool_allowed(key_row):
        return _err("UNAUTHORIZED", "API key is not permitted to invoke this tool", tool_name=tool_name, api_key_id=api_key_id)

    # -------- Create request row (received) --------
    now = _now_utc()
    now_iso = _iso(now)
    usage_date_iso = _day_bucket_iso(now)

    search_requests = _load("search_requests.json")
    if not isinstance(search_requests, list):
        search_requests = []

    search_results = _load("search_results.json")
    if not isinstance(search_results, list):
        search_results = []

    req_id = _gen_id("bsmcp_req")
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "query_text": q,
        "requested_limit": requested_limit,
        "effective_limit": effective_limit,
        "client_metadata": client_metadata,
        "upstream_provider": "brave",
        "upstream_request_id": _gen_id("brv"),
        "fallback_used": False,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "completed_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    search_requests.append(req_row)
    _save("search_requests.json", search_requests)

    # Load counters for quota decision (before "upstream")
    counters = _load("usage_counters.json")
    if not isinstance(counters, list):
        counters = []

    # -------- Enforce burst rate limit (approx) before execution --------
    if _rate_limited(counters, api_key_id, key_row.get("burst_rps_limit")):
        # Update request -> failed (no upstream)
        req_row["status"] = "failed"
        req_row["error_code"] = "rate_limited"
        req_row["error_message"] = "Upstream rate limit hit (HTTP 429); retry after 2s"
        req_row["completed_at"] = _iso(_now_utc())
        req_row["updated_at"] = req_row["completed_at"]
        _save("search_requests.json", search_requests)
        _increment_usage(api_key_id, usage_date_iso, "failed")
        return _err("RATE_LIMIT", "Rate limit exceeded", tool_name=tool_name, api_key_id=api_key_id)

    # -------- Enforce daily quota before execution --------
    try:
        daily_limit = int(key_row.get("daily_request_limit"))
    except Exception:
        daily_limit = 0

    if daily_limit >= 0:
        total_today = _sum_daily_requests(counters, api_key_id, usage_date_iso)
        # Business rule: reject when sum(request_count) ... MUST be <= limit; otherwise fail.
        if total_today >= daily_limit:
            req_row["status"] = "failed"
            req_row["error_code"] = "quota_exceeded"
            req_row["error_message"] = "Daily request quota exceeded for this API key"
            req_row["completed_at"] = _iso(_now_utc())
            req_row["updated_at"] = req_row["completed_at"]
            _save("search_requests.json", search_requests)
            _increment_usage(api_key_id, usage_date_iso, "failed")
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for this API key", tool_name=tool_name, api_key_id=api_key_id)

    # -------- "Execute upstream": mark running -> succeeded and generate normalized results --------
    req_row["status"] = "running"
    req_row["started_at"] = _iso(_now_utc())
    req_row["updated_at"] = req_row["started_at"]
    _save("search_requests.json", search_requests)

    # Generate deterministic-ish placeholder results (offline) while persisting real rows.
    # Must persist between 0 and effective_limit results; we persist effective_limit unless query is blank (already validated).
    results_out = []
    now_iso2 = _iso(_now_utc())

    # Ensure no pre-existing results for this request id (should not exist); if they do, keep unique ranks by skipping.
    existing_ranks = set()
    for r in search_results:
        if r.get("search_request_id") == req_id:
            try:
                existing_ranks.add(int(r.get("rank")))
            except Exception:
                pass

    next_rank = 1
    while next_rank in existing_ranks:
        next_rank += 1

    for i in range(effective_limit):
        rank = next_rank + i
        if rank > 20:
            break
        res_id = _gen_id("bsmcp_res")
        url = f"https://example.com/image/{req_id}/{rank}"
        item = {
            "id": res_id,
            "search_request_id": req_id,
            "rank": rank,
            "result_type": "image",
            "title": f"Image result {rank} for {q}",
            "url": url,
            "description": f"Offline image search result {rank}.",
            "source": "example.com",
            "published_at": None,
            "thumbnail_url": f"https://example.com/thumb/{req_id}/{rank}.jpg",
            "payload": {"query": q, "rank": rank},
            "created_at": now_iso2,
            "updated_at": now_iso2,
        }
        search_results.append(item)
        results_out.append(item)

    _save("search_results.json", search_results)

    req_row["status"] = "succeeded"
    req_row["completed_at"] = _iso(_now_utc())
    req_row["updated_at"] = req_row["completed_at"]
    _save("search_requests.json", search_requests)

    _increment_usage(api_key_id, usage_date_iso, "succeeded")

    return {
        "request": req_row,
        "results": results_out,
        "meta": {
            "requested_limit": requested_limit,
            "effective_limit": effective_limit,
            "returned": len(results_out),
            "tool_name": tool_name,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def brave_web_search(api_key, q, count=None, client_metadata=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0232000" if __import__("os").path.isdir("./environment_mix/0232000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool_name = "brave_web_search"

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if q is None:
        return _err("VALIDATION_ERROR", "q is required")
    if isinstance(q, (int, float, bool)):
        q_text = str(q)
    elif isinstance(q, str):
        q_text = q
    else:
        q_text = str(q)
    if not q_text.strip():
        return _err("VALIDATION_ERROR", "q must be non-empty")
    if count is None:
        requested_limit = 10
    else:
        if isinstance(count, bool):
            return _err("VALIDATION_ERROR", "count must be an integer")
        if not isinstance(count, int):
            return _err("VALIDATION_ERROR", "count must be an integer")
        requested_limit = count
    if client_metadata is not None and not isinstance(client_metadata, dict):
        return _err("VALIDATION_ERROR", "client_metadata must be an object")

    original_requested = requested_limit
    if requested_limit < 1:
        requested_limit = 1
    effective_limit = max(1, min(20, requested_limit))
    stored_requested_limit = requested_limit
    if isinstance(original_requested, int) and original_requested > 20:
        stored_requested_limit = 20
        if client_metadata is None:
            client_metadata = {}
        if isinstance(client_metadata, dict) and "original_requested_limit" not in client_metadata:
            client_metadata["original_requested_limit"] = original_requested

    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    search_results = _load("search_results.json")
    usage_counters = _load("usage_counters.json")

    key_row = None
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == api_key or r.get("key_prefix") == api_key:
            key_row = r
            break
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid api_key")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active", status=key_row.get("status"))
    allowed = key_row.get("allowed_tools")
    if isinstance(allowed, list) and len(allowed) > 0 and tool_name not in allowed:
        return _err("UNAUTHORIZED", "API key is not permitted to invoke this tool", tool_name=tool_name)

    api_key_id = key_row.get("id")
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now.isoformat().replace("+00:00", "Z")
    day_bucket = now.replace(hour=0, minute=0, second=0, microsecond=0).isoformat().replace("+00:00", "Z")

    # burst RPS limit (use search_requests as request log)
    window_start = now - datetime.timedelta(seconds=1)
    try:
        burst_val = float(key_row.get("burst_rps_limit", 0))
    except Exception:
        burst_val = 0.0
    if burst_val > 0:
        recent = 0
        for rr in search_requests:
            if not isinstance(rr, dict) or rr.get("api_key_id") != api_key_id:
                continue
            ts = rr.get("created_at")
            if not isinstance(ts, str) or not ts.endswith("Z"):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1]).replace(tzinfo=datetime.timezone.utc)
            except Exception:
                continue
            if dt >= window_start:
                recent += 1
        if recent >= int(burst_val + 1e-9):
            req_id = "bsmcp_req_" + uuid.uuid4().hex[:26]
            req_row = {
                "id": req_id,
                "api_key_id": api_key_id,
                "tool_name": tool_name,
                "query_text": q_text,
                "requested_limit": stored_requested_limit,
                "effective_limit": effective_limit,
                "client_metadata": client_metadata,
                "upstream_provider": "brave",
                "upstream_request_id": None,
                "fallback_used": False,
                "status": "failed",
                "error_code": "rate_limited",
                "error_message": "Burst rate limit exceeded",
                "started_at": None,
                "completed_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            search_requests.append(req_row)
            _save("search_requests.json", search_requests)

            counter_row = None
            for c in usage_counters:
                if isinstance(c, dict) and c.get("api_key_id") == api_key_id and c.get("usage_date") == day_bucket and c.get("tool_name") == tool_name:
                    counter_row = c
                    break
            if counter_row is None:
                counter_row = {
                    "id": "bsmcp_use_" + uuid.uuid4().hex[:26],
                    "api_key_id": api_key_id,
                    "usage_date": day_bucket,
                    "tool_name": tool_name,
                    "request_count": 0,
                    "success_count": 0,
                    "error_count": 0,
                    "created_at": now_iso,
                    "updated_at": now_iso,
                }
                usage_counters.append(counter_row)
            counter_row["request_count"] = int(counter_row.get("request_count", 0) or 0) + 1
            counter_row["error_count"] = int(counter_row.get("error_count", 0) or 0) + 1
            counter_row["updated_at"] = now_iso
            _save("usage_counters.json", usage_counters)
            return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=1, search_request_id=req_id)

    # daily quota check
    used_today = 0
    for c in usage_counters:
        if isinstance(c, dict) and c.get("api_key_id") == api_key_id and c.get("usage_date") == day_bucket:
            rc = c.get("request_count", 0)
            if isinstance(rc, int) and rc >= 0:
                used_today += rc
    daily_limit = key_row.get("daily_request_limit", 0)
    if not isinstance(daily_limit, int) or daily_limit < 0:
        daily_limit = 0

    req_id = "bsmcp_req_" + uuid.uuid4().hex[:26]
    upstream_id = "brv_" + uuid.uuid4().hex[:16]
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "query_text": q_text,
        "requested_limit": stored_requested_limit,
        "effective_limit": effective_limit,
        "client_metadata": client_metadata,
        "upstream_provider": "brave",
        "upstream_request_id": None,
        "fallback_used": False,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "completed_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    search_requests.append(req_row)
    _save("search_requests.json", search_requests)

    if daily_limit == 0 or used_today >= daily_limit:
        req_row["status"] = "failed"
        req_row["error_code"] = "quota_exceeded"
        req_row["error_message"] = "Daily request quota exceeded for this API key"
        req_row["completed_at"] = now_iso
        req_row["updated_at"] = now_iso
        _save("search_requests.json", search_requests)

        counter_row = None
        for c in usage_counters:
            if isinstance(c, dict) and c.get("api_key_id") == api_key_id and c.get("usage_date") == day_bucket and c.get("tool_name") == tool_name:
                counter_row = c
                break
        if counter_row is None:
            counter_row = {
                "id": "bsmcp_use_" + uuid.uuid4().hex[:26],
                "api_key_id": api_key_id,
                "usage_date": day_bucket,
                "tool_name": tool_name,
                "request_count": 0,
                "success_count": 0,
                "error_count": 0,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            usage_counters.append(counter_row)
        counter_row["request_count"] = int(counter_row.get("request_count", 0) or 0) + 1
        counter_row["error_count"] = int(counter_row.get("error_count", 0) or 0) + 1
        counter_row["updated_at"] = now_iso
        _save("usage_counters.json", usage_counters)

        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for this API key", search_request_id=req_id)

    # running -> succeeded and persist results
    req_row["status"] = "running"
    req_row["started_at"] = now_iso
    req_row["upstream_request_id"] = upstream_id
    req_row["updated_at"] = now_iso
    _save("search_requests.json", search_requests)

    created_iso = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    new_results = []
    for i in range(1, effective_limit + 1):
        rid = "bsmcp_res_" + uuid.uuid4().hex[:26]
        url = "https://example.com/web/" + base64.urlsafe_b64encode((q_text + ":" + str(i)).encode("utf-8")).decode("ascii").rstrip("=")
        new_results.append({
            "id": rid,
            "search_request_id": req_id,
            "rank": i,
            "result_type": "web",
            "title": f"Web result {i} for {q_text}",
            "url": url,
            "description": f"Placeholder web result for query '{q_text}'",
            "source": "example.com",
            "published_at": None,
            "thumbnail_url": None,
            "payload": {"query": q_text, "index": i},
            "created_at": created_iso,
            "updated_at": created_iso,
        })
    search_results = [r for r in search_results if not (isinstance(r, dict) and r.get("search_request_id") == req_id)]
    search_results.extend(new_results)
    _save("search_results.json", search_results)

    completed_iso = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    req_row["status"] = "succeeded"
    req_row["completed_at"] = completed_iso
    req_row["updated_at"] = completed_iso
    _save("search_requests.json", search_requests)

    counter_row = None
    for c in usage_counters:
        if isinstance(c, dict) and c.get("api_key_id") == api_key_id and c.get("usage_date") == day_bucket and c.get("tool_name") == tool_name:
            counter_row = c
            break
    if counter_row is None:
        counter_row = {
            "id": "bsmcp_use_" + uuid.uuid4().hex[:26],
            "api_key_id": api_key_id,
            "usage_date": day_bucket,
            "tool_name": tool_name,
            "request_count": 0,
            "success_count": 0,
            "error_count": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage_counters.append(counter_row)
    counter_row["request_count"] = int(counter_row.get("request_count", 0) or 0) + 1
    counter_row["success_count"] = int(counter_row.get("success_count", 0) or 0) + 1
    counter_row["updated_at"] = completed_iso
    _save("usage_counters.json", usage_counters)

    return {
        "search_request": req_row,
        "results": new_results,
        "meta": {
            "requested_limit": original_requested,
            "effective_limit": effective_limit,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def brave_local_search(api_key, q, count=None, client_metadata=None, fallback_to_web=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0232000" if __import__("os").path.isdir("./environment_mix/0232000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool_name = "brave_local_search"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _day_bucket_iso(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        b = datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)
        return _iso(b)

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s.strip():
            return None
        s2 = s.strip()
        try:
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000):013d}{random.randint(0, 999999):06d}"

    def _normalize_key_param(v):
        if not isinstance(v, str):
            return None
        return v.strip()

    def _coerce_int(v):
        if v is None:
            return None
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v
        if isinstance(v, str):
            s = v.strip()
            if s == "":
                return None
            try:
                return int(s)
            except Exception:
                return None
        return None

    def _auth_api_key(api_key_value):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        av = _normalize_key_param(api_key_value)
        if not av:
            return None

        candidates = []
        for r in keys:
            if not isinstance(r, dict):
                continue
            rid = r.get("id")
            pref = r.get("key_prefix")
            if rid == av:
                candidates.append(r)
            elif isinstance(pref, str) and pref and av.startswith(pref):
                candidates.append(r)

        if not candidates:
            return None
        for r in candidates:
            if r.get("status") == "active":
                return r
        return candidates[0]

    def _is_tool_allowed(key_row):
        allowed = key_row.get("allowed_tools")
        if allowed is None:
            return True
        if not isinstance(allowed, list):
            return False
        if len(allowed) == 0:
            return True
        return tool_name in allowed

    def _ensure_counter_row(counters, api_key_id, usage_date_iso):
        now_iso = _iso(_now_utc())
        for r in counters:
            if r.get("api_key_id") == api_key_id and r.get("usage_date") == usage_date_iso and r.get("tool_name") == tool_name:
                return r
        row = {
            "id": _gen_id("bsmcp_use"),
            "api_key_id": api_key_id,
            "usage_date": usage_date_iso,
            "tool_name": tool_name,
            "request_count": 0,
            "success_count": 0,
            "error_count": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        counters.append(row)
        return row

    def _increment_usage(api_key_id, usage_date_iso, final_status):
        counters = _load("usage_counters.json")
        if not isinstance(counters, list):
            counters = []
        row = _ensure_counter_row(counters, api_key_id, usage_date_iso)
        row["request_count"] = int(row.get("request_count") or 0) + 1
        if final_status == "succeeded":
            row["success_count"] = int(row.get("success_count") or 0) + 1
        else:
            row["error_count"] = int(row.get("error_count") or 0) + 1
        row["updated_at"] = _iso(_now_utc())
        sc = int(row.get("success_count") or 0)
        ec = int(row.get("error_count") or 0)
        rc = int(row.get("request_count") or 0)
        if sc + ec > rc:
            row["request_count"] = sc + ec
        _save("usage_counters.json", counters)

    def _sum_daily_requests(counters, api_key_id, usage_date_iso):
        total = 0
        for r in counters:
            if r.get("api_key_id") == api_key_id and r.get("usage_date") == usage_date_iso:
                try:
                    total += int(r.get("request_count") or 0)
                except Exception:
                    pass
        return total

    def _rate_limited(api_key_id, burst_rps_limit):
        try:
            limit = float(burst_rps_limit)
        except Exception:
            return False
        if limit <= 0:
            return False
        reqs = _load("search_requests.json")
        if not isinstance(reqs, list):
            return False
        now = _now_utc()
        window_start = now - datetime.timedelta(seconds=1)
        cnt = 0
        for r in reqs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            created = _parse_rfc3339(r.get("created_at"))
            if created is None:
                continue
            if created >= window_start:
                cnt += 1
        return cnt >= limit

    # -------- Validate inputs --------
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    if not isinstance(q, str) or not q.strip():
        return _err("VALIDATION_ERROR", "q must be a non-empty string", field="q")
    if client_metadata is not None and not isinstance(client_metadata, dict):
        return _err("VALIDATION_ERROR", "client_metadata must be an object", field="client_metadata")
    if fallback_to_web is not None and not isinstance(fallback_to_web, bool):
        return _err("VALIDATION_ERROR", "fallback_to_web must be a boolean", field="fallback_to_web")

    requested_limit = _coerce_int(count)
    if requested_limit is None:
        requested_limit = 20
    if requested_limit < 1:
        return _err("VALIDATION_ERROR", "count must be >= 1", field="count")
    effective_limit = max(1, min(20, requested_limit))

    # -------- Authenticate --------
    key_row = _auth_api_key(api_key)
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key", tool_name=tool_name)
    api_key_id = key_row.get("id")

    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active", tool_name=tool_name, api_key_id=api_key_id)
    if not _is_tool_allowed(key_row):
        return _err("UNAUTHORIZED", "API key is not permitted to invoke this tool", tool_name=tool_name, api_key_id=api_key_id)

    # -------- Create request row (received) --------
    now = _now_utc()
    now_iso = _iso(now)
    usage_date_iso = _day_bucket_iso(now)

    search_requests = _load("search_requests.json")
    if not isinstance(search_requests, list):
        search_requests = []

    search_results = _load("search_results.json")
    if not isinstance(search_results, list):
        search_results = []

    req_id = _gen_id("bsmcp_req")
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "query_text": q,
        "requested_limit": requested_limit,
        "effective_limit": effective_limit,
        "client_metadata": client_metadata,
        "upstream_provider": "brave",
        "upstream_request_id": _gen_id("brv"),
        "fallback_used": False,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "completed_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    search_requests.append(req_row)
    _save("search_requests.json", search_requests)

    counters = _load("usage_counters.json")
    if not isinstance(counters, list):
        counters = []

    # -------- Enforce burst rate limit before execution --------
    if _rate_limited(api_key_id, key_row.get("burst_rps_limit")):
        req_row["status"] = "failed"
        req_row["error_code"] = "rate_limited"
        req_row["error_message"] = "Upstream rate limit hit (HTTP 429); retry after 2s"
        req_row["completed_at"] = _iso(_now_utc())
        req_row["updated_at"] = req_row["completed_at"]
        _save("search_requests.json", search_requests)
        _increment_usage(api_key_id, usage_date_iso, "failed")
        return _err("RATE_LIMIT", "Rate limit exceeded", tool_name=tool_name, api_key_id=api_key_id)

    # -------- Enforce daily quota before execution --------
    try:
        daily_limit = int(key_row.get("daily_request_limit"))
    except Exception:
        daily_limit = 0
    total_today = _sum_daily_requests(counters, api_key_id, usage_date_iso)
    if daily_limit >= 0 and total_today >= daily_limit:
        req_row["status"] = "failed"
        req_row["error_code"] = "quota_exceeded"
        req_row["error_message"] = "Daily request quota exceeded for this API key"
        req_row["completed_at"] = _iso(_now_utc())
        req_row["updated_at"] = req_row["completed_at"]
        _save("search_requests.json", search_requests)
        _increment_usage(api_key_id, usage_date_iso, "failed")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for this API key", tool_name=tool_name, api_key_id=api_key_id)

    # -------- "Execute upstream": running -> succeeded; local may fallback to web --------
    req_row["status"] = "running"
    req_row["started_at"] = _iso(_now_utc())
    req_row["updated_at"] = req_row["started_at"]
    _save("search_requests.json", search_requests)

    # Offline heuristic: if query contains "near me" we pretend local succeeds; otherwise if fallback_to_web -> web results.
    fb = True if fallback_to_web is True else False
    wants_near = "near me" in q.lower()
    use_fallback = fb and not wants_near
    req_row["fallback_used"] = bool(use_fallback)

    results_out = []
    now_iso2 = _iso(_now_utc())

    existing_ranks = set()
    for r in search_results:
        if r.get("search_request_id") == req_id:
            try:
                existing_ranks.add(int(r.get("rank")))
            except Exception:
                pass
    next_rank = 1
    while next_rank in existing_ranks:
        next_rank += 1

    for i in range(effective_limit):
        rank = next_rank + i
        if rank > 20:
            break
        res_id = _gen_id("bsmcp_res")
        if use_fallback:
            rtype = "web"  # allowed by business rule when fallback_used=true
            url = f"https://example.com/web/{req_id}/{rank}"
            payload = {"query": q, "rank": rank, "fallback_from": "local"}
            title = f"Web fallback result {rank} for {q}"
            desc = f"Offline web fallback result {rank}."
            source = "example.com"
        else:
            rtype = "local"
            url = f"https://example.com/local/{req_id}/{rank}"
            payload = {"name": f"Place {rank}", "address": f"{rank} Main St", "phone": None, "query": q}
            title = f"Place {rank} for {q}"
            desc = f"Offline local place result {rank}."
            source = "example.com"

        item = {
            "id": res_id,
            "search_request_id": req_id,
            "rank": rank,
            "result_type": rtype,
            "title": title,
            "url": url,
            "description": desc,
            "source": source,
            "published_at": None,
            "thumbnail_url": None,
            "payload": payload,
            "created_at": now_iso2,
            "updated_at": now_iso2,
        }
        search_results.append(item)
        results_out.append(item)

    _save("search_results.json", search_results)

    req_row["status"] = "succeeded"
    req_row["completed_at"] = _iso(_now_utc())
    req_row["updated_at"] = req_row["completed_at"]
    _save("search_requests.json", search_requests)

    _increment_usage(api_key_id, usage_date_iso, "succeeded")

    return {
        "request": req_row,
        "results": results_out,
        "meta": {
            "requested_limit": requested_limit,
            "effective_limit": effective_limit,
            "returned": len(results_out),
            "tool_name": tool_name,
            "fallback_used": req_row["fallback_used"],
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def brave_news_search(api_key, q, count=None, client_metadata=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0232000" if __import__("os").path.isdir("./environment_mix/0232000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool_name = "brave_news_search"

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if q is None:
        return _err("VALIDATION_ERROR", "q is required")
    if isinstance(q, (int, float, bool)):
        q_text = str(q)
    elif isinstance(q, str):
        q_text = q
    else:
        q_text = str(q)
    if not q_text.strip():
        return _err("VALIDATION_ERROR", "q must be non-empty")
    if count is None:
        requested_limit = 10
    else:
        if isinstance(count, bool):
            return _err("VALIDATION_ERROR", "count must be an integer")
        if not isinstance(count, int):
            return _err("VALIDATION_ERROR", "count must be an integer")
        requested_limit = count
    if client_metadata is not None and not isinstance(client_metadata, dict):
        return _err("VALIDATION_ERROR", "client_metadata must be an object")

    original_requested = requested_limit
    if requested_limit < 1:
        requested_limit = 1
    effective_limit = max(1, min(20, requested_limit))
    stored_requested_limit = requested_limit
    if isinstance(original_requested, int) and original_requested > 20:
        stored_requested_limit = 20
        if client_metadata is None:
            client_metadata = {}
        if isinstance(client_metadata, dict) and "original_requested_limit" not in client_metadata:
            client_metadata["original_requested_limit"] = original_requested

    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    search_results = _load("search_results.json")
    usage_counters = _load("usage_counters.json")

    key_row = None
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == api_key or r.get("key_prefix") == api_key:
            key_row = r
            break
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid api_key")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active", status=key_row.get("status"))
    allowed = key_row.get("allowed_tools")
    if isinstance(allowed, list) and len(allowed) > 0 and tool_name not in allowed:
        return _err("UNAUTHORIZED", "API key is not permitted to invoke this tool", tool_name=tool_name)

    api_key_id = key_row.get("id")
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now_iso = now.isoformat().replace("+00:00", "Z")
    day_bucket = now.replace(hour=0, minute=0, second=0, microsecond=0).isoformat().replace("+00:00", "Z")

    # burst RPS check
    window_start = now - datetime.timedelta(seconds=1)
    try:
        burst_val = float(key_row.get("burst_rps_limit", 0))
    except Exception:
        burst_val = 0.0
    if burst_val > 0:
        recent = 0
        for rr in search_requests:
            if not isinstance(rr, dict) or rr.get("api_key_id") != api_key_id:
                continue
            ts = rr.get("created_at")
            if not isinstance(ts, str) or not ts.endswith("Z"):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1]).replace(tzinfo=datetime.timezone.utc)
            except Exception:
                continue
            if dt >= window_start:
                recent += 1
        if recent >= int(burst_val + 1e-9):
            req_id = "bsmcp_req_" + uuid.uuid4().hex[:26]
            req_row = {
                "id": req_id,
                "api_key_id": api_key_id,
                "tool_name": tool_name,
                "query_text": q_text,
                "requested_limit": stored_requested_limit,
                "effective_limit": effective_limit,
                "client_metadata": client_metadata,
                "upstream_provider": "brave",
                "upstream_request_id": None,
                "fallback_used": False,
                "status": "failed",
                "error_code": "rate_limited",
                "error_message": "Burst rate limit exceeded",
                "started_at": None,
                "completed_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            search_requests.append(req_row)
            _save("search_requests.json", search_requests)

            counter_row = None
            for c in usage_counters:
                if isinstance(c, dict) and c.get("api_key_id") == api_key_id and c.get("usage_date") == day_bucket and c.get("tool_name") == tool_name:
                    counter_row = c
                    break
            if counter_row is None:
                counter_row = {
                    "id": "bsmcp_use_" + uuid.uuid4().hex[:26],
                    "api_key_id": api_key_id,
                    "usage_date": day_bucket,
                    "tool_name": tool_name,
                    "request_count": 0,
                    "success_count": 0,
                    "error_count": 0,
                    "created_at": now_iso,
                    "updated_at": now_iso,
                }
                usage_counters.append(counter_row)
            counter_row["request_count"] = int(counter_row.get("request_count", 0) or 0) + 1
            counter_row["error_count"] = int(counter_row.get("error_count", 0) or 0) + 1
            counter_row["updated_at"] = now_iso
            _save("usage_counters.json", usage_counters)
            return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=1, search_request_id=req_id)

    # daily quota
    used_today = 0
    for c in usage_counters:
        if isinstance(c, dict) and c.get("api_key_id") == api_key_id and c.get("usage_date") == day_bucket:
            rc = c.get("request_count", 0)
            if isinstance(rc, int) and rc >= 0:
                used_today += rc
    daily_limit = key_row.get("daily_request_limit", 0)
    if not isinstance(daily_limit, int) or daily_limit < 0:
        daily_limit = 0

    req_id = "bsmcp_req_" + uuid.uuid4().hex[:26]
    upstream_id = "brv_" + uuid.uuid4().hex[:16]
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "query_text": q_text,
        "requested_limit": stored_requested_limit,
        "effective_limit": effective_limit,
        "client_metadata": client_metadata,
        "upstream_provider": "brave",
        "upstream_request_id": None,
        "fallback_used": False,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "completed_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    search_requests.append(req_row)
    _save("search_requests.json", search_requests)

    if daily_limit == 0 or used_today >= daily_limit:
        req_row["status"] = "failed"
        req_row["error_code"] = "quota_exceeded"
        req_row["error_message"] = "Daily request quota exceeded for this API key"
        req_row["completed_at"] = now_iso
        req_row["updated_at"] = now_iso
        _save("search_requests.json", search_requests)

        counter_row = None
        for c in usage_counters:
            if isinstance(c, dict) and c.get("api_key_id") == api_key_id and c.get("usage_date") == day_bucket and c.get("tool_name") == tool_name:
                counter_row = c
                break
        if counter_row is None:
            counter_row = {
                "id": "bsmcp_use_" + uuid.uuid4().hex[:26],
                "api_key_id": api_key_id,
                "usage_date": day_bucket,
                "tool_name": tool_name,
                "request_count": 0,
                "success_count": 0,
                "error_count": 0,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            usage_counters.append(counter_row)
        counter_row["request_count"] = int(counter_row.get("request_count", 0) or 0) + 1
        counter_row["error_count"] = int(counter_row.get("error_count", 0) or 0) + 1
        counter_row["updated_at"] = now_iso
        _save("usage_counters.json", usage_counters)

        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for this API key", search_request_id=req_id)

    # running -> succeeded, persist results
    req_row["status"] = "running"
    req_row["started_at"] = now_iso
    req_row["upstream_request_id"] = upstream_id
    req_row["updated_at"] = now_iso
    _save("search_requests.json", search_requests)

    created_iso = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    new_results = []
    for i in range(1, effective_limit + 1):
        rid = "bsmcp_res_" + uuid.uuid4().hex[:26]
        url = "https://example.com/news/" + base64.urlsafe_b64encode((q_text + ":" + str(i)).encode("utf-8")).decode("ascii").rstrip("=")
        published = (now - datetime.timedelta(days=i)).isoformat().replace("+00:00", "Z")
        new_results.append({
            "id": rid,
            "search_request_id": req_id,
            "rank": i,
            "result_type": "news",
            "title": f"News result {i} for {q_text}",
            "url": url,
            "description": f"Placeholder news result for query '{q_text}'",
            "source": "example.com",
            "published_at": published,
            "thumbnail_url": None,
            "payload": {"query": q_text, "index": i},
            "created_at": created_iso,
            "updated_at": created_iso,
        })
    search_results = [r for r in search_results if not (isinstance(r, dict) and r.get("search_request_id") == req_id)]
    search_results.extend(new_results)
    _save("search_results.json", search_results)

    completed_iso = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
    req_row["status"] = "succeeded"
    req_row["completed_at"] = completed_iso
    req_row["updated_at"] = completed_iso
    _save("search_requests.json", search_requests)

    counter_row = None
    for c in usage_counters:
        if isinstance(c, dict) and c.get("api_key_id") == api_key_id and c.get("usage_date") == day_bucket and c.get("tool_name") == tool_name:
            counter_row = c
            break
    if counter_row is None:
        counter_row = {
            "id": "bsmcp_use_" + uuid.uuid4().hex[:26],
            "api_key_id": api_key_id,
            "usage_date": day_bucket,
            "tool_name": tool_name,
            "request_count": 0,
            "success_count": 0,
            "error_count": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage_counters.append(counter_row)
    counter_row["request_count"] = int(counter_row.get("request_count", 0) or 0) + 1
    counter_row["success_count"] = int(counter_row.get("success_count", 0) or 0) + 1
    counter_row["updated_at"] = completed_iso
    _save("usage_counters.json", usage_counters)

    return {
        "search_request": req_row,
        "results": new_results,
        "meta": {
            "requested_limit": original_requested,
            "effective_limit": effective_limit,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def brave_video_search(api_key, q, count=None, client_metadata=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0232000" if __import__("os").path.isdir("./environment_mix/0232000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool_name = "brave_video_search"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _day_bucket_iso(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        b = datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)
        return _iso(b)

    def _parse_rfc3339(s):
        if not isinstance(s, str) or not s.strip():
            return None
        s2 = s.strip()
        try:
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000):013d}{random.randint(0, 999999):06d}"

    def _normalize_key_param(v):
        if not isinstance(v, str):
            return None
        return v.strip()

    def _coerce_int(v):
        if v is None:
            return None
        if isinstance(v, bool):
            return None
        if isinstance(v, int):
            return v
        if isinstance(v, str):
            s = v.strip()
            if s == "":
                return None
            try:
                return int(s)
            except Exception:
                return None
        return None

    def _auth_api_key(api_key_value):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        av = _normalize_key_param(api_key_value)
        if not av:
            return None

        candidates = []
        for r in keys:
            if not isinstance(r, dict):
                continue
            rid = r.get("id")
            pref = r.get("key_prefix")
            if rid == av:
                candidates.append(r)
            elif isinstance(pref, str) and pref and av.startswith(pref):
                candidates.append(r)

        if not candidates:
            return None
        for r in candidates:
            if r.get("status") == "active":
                return r
        return candidates[0]

    def _is_tool_allowed(key_row):
        allowed = key_row.get("allowed_tools")
        if allowed is None:
            return True
        if not isinstance(allowed, list):
            return False
        if len(allowed) == 0:
            return True
        return tool_name in allowed

    def _ensure_counter_row(counters, api_key_id, usage_date_iso):
        now_iso = _iso(_now_utc())
        for r in counters:
            if r.get("api_key_id") == api_key_id and r.get("usage_date") == usage_date_iso and r.get("tool_name") == tool_name:
                return r
        row = {
            "id": _gen_id("bsmcp_use"),
            "api_key_id": api_key_id,
            "usage_date": usage_date_iso,
            "tool_name": tool_name,
            "request_count": 0,
            "success_count": 0,
            "error_count": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        counters.append(row)
        return row

    def _increment_usage(api_key_id, usage_date_iso, final_status):
        counters = _load("usage_counters.json")
        if not isinstance(counters, list):
            counters = []
        row = _ensure_counter_row(counters, api_key_id, usage_date_iso)
        row["request_count"] = int(row.get("request_count") or 0) + 1
        if final_status == "succeeded":
            row["success_count"] = int(row.get("success_count") or 0) + 1
        else:
            row["error_count"] = int(row.get("error_count") or 0) + 1
        row["updated_at"] = _iso(_now_utc())
        sc = int(row.get("success_count") or 0)
        ec = int(row.get("error_count") or 0)
        rc = int(row.get("request_count") or 0)
        if sc + ec > rc:
            row["request_count"] = sc + ec
        _save("usage_counters.json", counters)

    def _sum_daily_requests(counters, api_key_id, usage_date_iso):
        total = 0
        for r in counters:
            if r.get("api_key_id") == api_key_id and r.get("usage_date") == usage_date_iso:
                try:
                    total += int(r.get("request_count") or 0)
                except Exception:
                    pass
        return total

    def _rate_limited(api_key_id, burst_rps_limit):
        try:
            limit = float(burst_rps_limit)
        except Exception:
            return False
        if limit <= 0:
            return False
        reqs = _load("search_requests.json")
        if not isinstance(reqs, list):
            return False
        now = _now_utc()
        window_start = now - datetime.timedelta(seconds=1)
        cnt = 0
        for r in reqs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            created = _parse_rfc3339(r.get("created_at"))
            if created is None:
                continue
            if created >= window_start:
                cnt += 1
        return cnt >= limit

    # -------- Validate inputs --------
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    if not isinstance(q, str) or not q.strip():
        return _err("VALIDATION_ERROR", "q must be a non-empty string", field="q")
    if client_metadata is not None and not isinstance(client_metadata, dict):
        return _err("VALIDATION_ERROR", "client_metadata must be an object", field="client_metadata")

    requested_limit = _coerce_int(count)
    if requested_limit is None:
        requested_limit = 20
    if requested_limit < 1:
        return _err("VALIDATION_ERROR", "count must be >= 1", field="count")
    effective_limit = max(1, min(20, requested_limit))

    # -------- Authenticate --------
    key_row = _auth_api_key(api_key)
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key", tool_name=tool_name)
    api_key_id = key_row.get("id")

    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active", tool_name=tool_name, api_key_id=api_key_id)
    if not _is_tool_allowed(key_row):
        return _err("UNAUTHORIZED", "API key is not permitted to invoke this tool", tool_name=tool_name, api_key_id=api_key_id)

    # -------- Create request row (received) --------
    now = _now_utc()
    now_iso = _iso(now)
    usage_date_iso = _day_bucket_iso(now)

    search_requests = _load("search_requests.json")
    if not isinstance(search_requests, list):
        search_requests = []

    search_results = _load("search_results.json")
    if not isinstance(search_results, list):
        search_results = []

    req_id = _gen_id("bsmcp_req")
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": tool_name,
        "query_text": q,
        "requested_limit": requested_limit,
        "effective_limit": effective_limit,
        "client_metadata": client_metadata,
        "upstream_provider": "brave",
        "upstream_request_id": _gen_id("brv"),
        "fallback_used": False,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "started_at": None,
        "completed_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    search_requests.append(req_row)
    _save("search_requests.json", search_requests)

    counters = _load("usage_counters.json")
    if not isinstance(counters, list):
        counters = []

    # -------- Enforce burst rate limit before execution --------
    if _rate_limited(api_key_id, key_row.get("burst_rps_limit")):
        req_row["status"] = "failed"
        req_row["error_code"] = "rate_limited"
        req_row["error_message"] = "Upstream rate limit hit (HTTP 429); retry after 2s"
        req_row["completed_at"] = _iso(_now_utc())
        req_row["updated_at"] = req_row["completed_at"]
        _save("search_requests.json", search_requests)
        _increment_usage(api_key_id, usage_date_iso, "failed")
        return _err("RATE_LIMIT", "Rate limit exceeded", tool_name=tool_name, api_key_id=api_key_id)

    # -------- Enforce daily quota before execution --------
    try:
        daily_limit = int(key_row.get("daily_request_limit"))
    except Exception:
        daily_limit = 0
    total_today = _sum_daily_requests(counters, api_key_id, usage_date_iso)
    if daily_limit >= 0 and total_today >= daily_limit:
        req_row["status"] = "failed"
        req_row["error_code"] = "quota_exceeded"
        req_row["error_message"] = "Daily request quota exceeded for this API key"
        req_row["completed_at"] = _iso(_now_utc())
        req_row["updated_at"] = req_row["completed_at"]
        _save("search_requests.json", search_requests)
        _increment_usage(api_key_id, usage_date_iso, "failed")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for this API key", tool_name=tool_name, api_key_id=api_key_id)

    # -------- "Execute upstream": mark running -> succeeded and generate normalized results --------
    req_row["status"] = "running"
    req_row["started_at"] = _iso(_now_utc())
    req_row["updated_at"] = req_row["started_at"]
    _save("search_requests.json", search_requests)

    results_out = []
    now_iso2 = _iso(_now_utc())

    existing_ranks = set()
    for r in search_results:
        if r.get("search_request_id") == req_id:
            try:
                existing_ranks.add(int(r.get("rank")))
            except Exception:
                pass
    next_rank = 1
    while next_rank in existing_ranks:
        next_rank += 1

    for i in range(effective_limit):
        rank = next_rank + i
        if rank > 20:
            break
        res_id = _gen_id("bsmcp_res")
        url = f"https://example.com/video/{req_id}/{rank}"
        item = {
            "id": res_id,
            "search_request_id": req_id,
            "rank": rank,
            "result_type": "video",
            "title": f"Video result {rank} for {q}",
            "url": url,
            "description": f"Offline video search result {rank}.",
            "source": "example.com",
            "published_at": None,
            "thumbnail_url": f"https://example.com/vthumb/{req_id}/{rank}.jpg",
            "payload": {"query": q, "rank": rank, "duration_seconds": 60 + rank},
            "created_at": now_iso2,
            "updated_at": now_iso2,
        }
        search_results.append(item)
        results_out.append(item)

    _save("search_results.json", search_results)

    req_row["status"] = "succeeded"
    req_row["completed_at"] = _iso(_now_utc())
    req_row["updated_at"] = req_row["completed_at"]
    _save("search_requests.json", search_requests)

    _increment_usage(api_key_id, usage_date_iso, "succeeded")

    return {
        "request": req_row,
        "results": results_out,
        "meta": {
            "requested_limit": requested_limit,
            "effective_limit": effective_limit,
            "returned": len(results_out),
            "tool_name": tool_name,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def get_whoami(api_key, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0232000" if __import__("os").path.isdir("./environment_mix/0232000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    api_keys = _load("api_keys.json")
    usage_counters = _load("usage_counters.json")

    key_row = None
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == api_key or r.get("key_prefix") == api_key:
            key_row = r
            break
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid api_key")

    # Spec says FORBIDDEN for suspended/revoked; contract doesn't include FORBIDDEN. Use UNAUTHORIZED with detail.
    if key_row.get("status") in ("suspended", "revoked"):
        return _err("UNAUTHORIZED", "API key is not permitted", status=key_row.get("status"))

    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    day_bucket = now.replace(hour=0, minute=0, second=0, microsecond=0).isoformat().replace("+00:00", "Z")

    api_key_id = key_row.get("id")
    todays = [c for c in usage_counters if isinstance(c, dict) and c.get("api_key_id") == api_key_id and c.get("usage_date") == day_bucket]

    used_today = 0
    per_tool = {}
    for c in todays:
        rc = c.get("request_count", 0)
        if isinstance(rc, int) and rc >= 0:
            used_today += rc
        tn = c.get("tool_name")
        if isinstance(tn, str) and tn:
            per_tool[tn] = {
                "request_count": c.get("request_count", 0),
                "success_count": c.get("success_count", 0),
                "error_count": c.get("error_count", 0),
            }

    daily_limit = key_row.get("daily_request_limit", 0)
    if not isinstance(daily_limit, int) or daily_limit < 0:
        daily_limit = 0

    return {
        "api_key": {
            "id": key_row.get("id"),
            "key_prefix": key_row.get("key_prefix"),
            "label": key_row.get("label"),
            "status": key_row.get("status"),
            "daily_request_limit": daily_limit,
            "burst_rps_limit": key_row.get("burst_rps_limit"),
            "allowed_tools": key_row.get("allowed_tools") if isinstance(key_row.get("allowed_tools"), list) else [],
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
            "revoked_at": key_row.get("revoked_at"),
        },
        "quota": {
            "usage_date": day_bucket,
            "used_requests": used_today,
            "daily_request_limit": daily_limit,
            "remaining_requests": max(0, daily_limit - used_today) if daily_limit > 0 else 0,
            "per_tool": per_tool,
        },
    }

def list_search_requests(api_key, status=None, tool_name=None, q_contains=None, created_after=None, created_before=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0232000" if __import__("os").path.isdir("./environment_mix/0232000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    status_enum = {"received", "running", "succeeded", "failed", "cancelled"}
    tool_enum = {"brave_web_search", "brave_news_search", "brave_image_search", "brave_video_search", "brave_local_search"}

    if status is not None and (not isinstance(status, str) or status not in status_enum):
        return _err("VALIDATION_ERROR", "status must be one of received, running, succeeded, failed, cancelled")
    if tool_name is not None and (not isinstance(tool_name, str) or tool_name not in tool_enum):
        return _err("VALIDATION_ERROR", "tool_name must be one of brave_web_search, brave_news_search, brave_image_search, brave_video_search, brave_local_search")
    if q_contains is not None and not isinstance(q_contains, str):
        return _err("VALIDATION_ERROR", "q_contains must be a string")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")
    if page_token is not None and not isinstance(page_token, str):
        return _err("VALIDATION_ERROR", "page_token must be a string")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return "BAD"
        st = s.strip()
        try:
            if st.endswith("Z"):
                dt = datetime.datetime.fromisoformat(st[:-1]).replace(tzinfo=datetime.timezone.utc)
            else:
                dt = datetime.datetime.fromisoformat(st)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
            return dt
        except Exception:
            return "BAD"

    ca = _parse_rfc3339(created_after)
    if ca == "BAD":
        return _err("VALIDATION_ERROR", "created_after must be an RFC 3339 timestamp")
    cb = _parse_rfc3339(created_before)
    if cb == "BAD":
        return _err("VALIDATION_ERROR", "created_before must be an RFC 3339 timestamp")

    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")

    key_row = None
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == api_key or r.get("key_prefix") == api_key:
            key_row = r
            break
    if key_row is None or key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "Invalid or inactive api_key")

    api_key_id = key_row.get("id")

    # pagination: page_token is base64 of an integer offset
    offset = 0
    if page_token:
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                offset = 0
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid page_token")

    rows = []
    q_sub = q_contains.lower() if isinstance(q_contains, str) else None

    for r in search_requests:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != api_key_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if q_sub is not None:
            qt = r.get("query_text")
            if not isinstance(qt, str) or q_sub not in qt.lower():
                continue
        if ca is not None or cb is not None:
            ts = r.get("created_at")
            if isinstance(ts, str) and ts.endswith("Z"):
                try:
                    dt = datetime.datetime.fromisoformat(ts[:-1]).replace(tzinfo=datetime.timezone.utc)
                except Exception:
                    dt = None
            else:
                dt = None
            if dt is not None:
                if ca is not None and dt < ca:
                    continue
                if cb is not None and dt > cb:
                    continue
        rows.append(r)

    # order by created_at desc (fallback: id desc)
    def _sort_key(x):
        ts = x.get("created_at")
        if isinstance(ts, str) and ts.endswith("Z"):
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1])
                return (dt, x.get("id") or "")
            except Exception:
                pass
        return (datetime.datetime(1970, 1, 1), x.get("id") or "")

    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    page = rows[offset:offset + page_size]
    next_off = offset + len(page)
    has_more = next_off < total
    next_token = None
    if has_more:
        next_token = base64.urlsafe_b64encode(str(next_off).encode("utf-8")).decode("utf-8")

    return {
        "data": page,
        "page": {
            "total": total,
            "page_size": page_size,
            "has_more": has_more,
            "next_page_token": next_token,
        },
    }

