    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active", status=key_row.get("status"))

    api_key_id = key_row.get("id")

    req = None
    for r in search_requests:
        if isinstance(r, dict) and r.get("id") == search_request_id and r.get("api_key_id") == api_key_id:
            req = r
            break
    if req is None:
        return _err("NOT_FOUND", "Search request not found")

    results = [it for it in search_results if isinstance(it, dict) and it.get("search_request_id") == search_request_id]
    try:
        results.sort(key=lambda x: int(x.get("rank", 10**9)))
    except Exception:
        pass

    return {
        "search_request": req,
        "results": results,
        "meta": {"result_count": len(results)},
    }

def list_search_results(api_key, search_request_id, result_type=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0232000" if __import__("os").path.isdir("./environment_mix/0232000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(search_request_id, str) or not search_request_id.strip():
        return _err("VALIDATION_ERROR", "search_request_id must be a non-empty string")

    allowed_result_types = {"web", "news", "image", "video", "local"}
    if result_type is not None and (not isinstance(result_type, str) or result_type not in allowed_result_types):
        return _err("VALIDATION_ERROR", "result_type must be one of web, news, image, video, local")

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")
    if page_token is not None and not isinstance(page_token, str):
        return _err("VALIDATION_ERROR", "page_token must be a string")

    api_keys = _load("api_keys.json")
    search_requests = _load("search_requests.json")
    search_results = _load("search_results.json")

    key_row = None
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == api_key or r.get("key_prefix") == api_key:
            key_row = r
            break
    if key_row is None or key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "Invalid or inactive api_key")
    api_key_id = key_row.get("id")

    parent = None
    for r in search_requests:
        if isinstance(r, dict) and r.get("id") == search_request_id and r.get("api_key_id") == api_key_id:
            parent = r
            break
    if parent is None:
        return _err("NOT_FOUND", "Search request not found")

    offset = 0
    if page_token:
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                offset = 0
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid page_token")

    rows = []
    for it in search_results:
        if not isinstance(it, dict):
            continue
        if it.get("search_request_id") != search_request_id:
            continue
        if result_type is not None and it.get("result_type") != result_type:
            continue
        rows.append(it)

    try:
        rows.sort(key=lambda x: int(x.get("rank", 10**9)))
    except Exception:
        pass

    total = len(rows)
    page = rows[offset:offset + page_size]
    next_off = offset + len(page)
    has_more = next_off < total
    next_token = base64.urlsafe_b64encode(str(next_off).encode("utf-8")).decode("utf-8") if has_more else None

    return {
        "data": page,
        "page": {
            "total": total,
            "page_size": page_size,
            "has_more": has_more,
            "next_page_token": next_token,
        },
    }

def update_search_request(api_key, search_request_id, status=None, upstream_provider=None, upstream_request_id=None, fallback_used=None, error_code=None, error_message=None, started_at=None, completed_at=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0232000" if __import__("os").path.isdir("./environment_mix/0232000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception: 
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: 
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    tool_name = "update_search_request"

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        s2 = s.strip()
        if not s2:
            return None
        try:
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    # validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(search_request_id, str) or not search_request_id.strip():
        return _err("VALIDATION_ERROR", "search_request_id must be a non-empty string")

    status_enum = {"received", "running", "succeeded", "failed", "cancelled"}
    if status is not None and (not isinstance(status, str) or status not in status_enum):
        return _err("VALIDATION_ERROR", "status must be one of received, running, succeeded, failed, cancelled")

    if upstream_provider is not None and (not isinstance(upstream_provider, str) or not upstream_provider.strip()):
        return _err("VALIDATION_ERROR", "upstream_provider must be a non-empty string")
    if upstream_provider is not None and upstream_provider != "brave":
        return _err("VALIDATION_ERROR", "upstream_provider must be 'brave'")

    if upstream_request_id is not None and (not isinstance(upstream_request_id, str) or not upstream_request_id.strip()):
        return _err("VALIDATION_ERROR", "upstream_request_id must be a non-empty string")

    if fallback_used is not None and not isinstance(fallback_used, bool):
        return _err("VALIDATION_ERROR", "fallback_used must be a boolean")

    if error_code is not None and not isinstance(error_code, str):
        return _err("VALIDATION_ERROR", "error_code must be a string")
    if error_message is not None and not isinstance(error_message, str):
        return _err("VALIDATION_ERROR", "error_message must be a string")

    if started_at is not None and _parse_rfc3339(started_at) is None:
        return _err("VALIDATION_ERROR", "started_at must be an RFC3339 timestamp string")
    if completed_at is not None and _parse_rfc3339(completed_at) is None:
        return _err("VALIDATION_ERROR", "completed_at must be an RFC3339 timestamp string")

    # authenticate api key by id or key_prefix (never by hash plaintext)
    keys = _load("api_keys.json")
    key_row = None
    for r in keys:
        if r.get("id") == api_key:
            key_row = r
            break
    if key_row is None:
        for r in keys:
            if r.get("key_prefix") == api_key:
                key_row = r
                break
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid API key", tool_name=tool_name)

    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active", api_key_id=key_row.get("id"), status=key_row.get("status"))

    # locate search request (ownership enforced)
    requests = _load("search_requests.json")
    req = None
    for r in requests:
        if r.get("id") == search_request_id:
            req = r
            break
    if req is None or req.get("api_key_id") != key_row.get("id"):
        return _err("NOT_FOUND", "Search request not found or not owned by caller", search_request_id=search_request_id)

    # enforce lifecycle transitions
    transitions = {
        "received": {"running", "cancelled"},
        "running": {"succeeded", "failed", "cancelled"},
        "succeeded": set(),
        "failed": set(),
        "cancelled": set(),
    }
    current_status = req.get("status")
    if current_status not in transitions:
        return _err("CONFLICT", "Search request has invalid stored status", search_request_id=search_request_id, stored_status=current_status)

    if status is not None:
        if status != current_status:
            if status not in transitions.get(current_status, set()):
                return _err(
                    "INVALID_TRANSITION",
                    f"Illegal status transition {current_status} → {status} (allowed: {sorted(transitions.get(current_status, set()))})",
                    search_request_id=search_request_id,
                    from_status=current_status,
                    to_status=status,
                )
        # idempotent if same status
        req["status"] = status

    # business rules about terminal states
    terminal = {"succeeded", "failed", "cancelled"}
    if current_status in terminal and status is not None and status != current_status:
        return _err("INVALID_TRANSITION", f"A search_request MUST NOT transition out of '{current_status}'", search_request_id=search_request_id)

    # completion_at implies terminal status (schema constraint)
    effective_status = req.get("status")
    if completed_at is not None and effective_status not in terminal:
        return _err("VALIDATION_ERROR", "completed_at requires status in ('succeeded','failed','cancelled')", search_request_id=search_request_id, status=effective_status)

    # error_code/message should only be set when failed (relax: allow clearing on non-failed)
    if effective_status != "failed" and (error_code is not None or error_message is not None):
        # real services sometimes set diagnostic fields even when cancelled; but schema says for failures.
        return _err("VALIDATION_ERROR", "error_code/error_message may only be set when status='failed'", search_request_id=search_request_id, status=effective_status)

    # apply mutable fields
    if upstream_provider is not None:
        req["upstream_provider"] = upstream_provider
    if upstream_request_id is not None:
        req["upstream_request_id"] = upstream_request_id
    if fallback_used is not None:
        req["fallback_used"] = fallback_used
    if error_code is not None:
        req["error_code"] = error_code
    if error_message is not None:
        req["error_message"] = error_message
    if started_at is not None:
        req["started_at"] = started_at
    if completed_at is not None:
        req["completed_at"] = completed_at

    req["updated_at"] = _iso(_now_utc())

    _save("search_requests.json", requests)
    latency_ms = int((time.time() - t0) * 1000)
    return {"search_request": req, "meta": {"latency_ms": latency_ms}}

def list_usage_counters(api_key, usage_date=None, tool_name=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0232000" if __import__("os").path.isdir("./environment_mix/0232000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    if usage_date is not None:
        if not isinstance(usage_date, str):
            return _err("VALIDATION_ERROR", "usage_date must be a string")
        if re.match(r"^\d{4}-\d{2}-\d{2}$", usage_date) is None:
            return _err("VALIDATION_ERROR", "usage_date must be in YYYY-MM-DD format")

    allowed_tools = {"brave_web_search", "brave_news_search", "brave_image_search", "brave_video_search", "brave_local_search"}
    if tool_name is not None and (not isinstance(tool_name, str) or tool_name not in allowed_tools):
        return _err("VALIDATION_ERROR", "tool_name must be one of brave_web_search, brave_news_search, brave_image_search, brave_video_search, brave_local_search")

    if page_size is None:
        page_size = 100
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1 or page_size > 366:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 366")
    if page_token is not None and not isinstance(page_token, str):
        return _err("VALIDATION_ERROR", "page_token must be a string")

    api_keys = _load("api_keys.json")
    usage_counters = _load("usage_counters.json")

    key_row = None
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == api_key or r.get("key_prefix") == api_key:
            key_row = r
            break
    if key_row is None or key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "Invalid or inactive api_key")

    api_key_id = key_row.get("id")

    offset = 0
    if page_token:
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                offset = 0
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid page_token")

    date_filter = None
    if usage_date is not None:
        # store uses midnight UTC timestamps like 2026-06-03T00:00:00Z
        date_filter = usage_date + "T00:00:00Z"

    rows = []
    for c in usage_counters:
        if not isinstance(c, dict):
            continue
        if c.get("api_key_id") != api_key_id:
            continue
        if date_filter is not None and c.get("usage_date") != date_filter:
            continue
        if tool_name is not None and c.get("tool_name") != tool_name:
            continue
        rows.append(c)

    # order by usage_date desc, tool_name asc
    def _sort_key(x):
        ud = x.get("usage_date") or ""
        try:
            if isinstance(ud, str) and ud.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ud[:-1])
            else:
                dt = datetime.datetime(1970, 1, 1)
        except Exception:
            dt = datetime.datetime(1970, 1, 1)
        return (dt, x.get("tool_name") or "")

    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    page = rows[offset:offset + page_size]
    next_off = offset + len(page)
    has_more = next_off < total
    next_token = base64.urlsafe_b64encode(str(next_off).encode("utf-8")).decode("utf-8") if has_more else None

    return {
        "data": page,
        "page": {
            "total": total,
            "page_size": page_size,
            "has_more": has_more,
            "next_page_token": next_token,
        },
    }
